#!/bin/bash\n# Git 身份自动配置 - 恢复/重新启用脚本\n# 用于在禁用后重新启用自动配置\n# 用法: bash tools/enable_git_identity_hook.sh\n\nset -e\n\necho \"=======================================================================\"\necho \"   Git 身份自动配置 - 恢复脚本\"\necho \"=======================================================================\"\necho \"\"\n\n# 检查是否已启用\nBASHRC=\"$HOME/.bashrc\"\nif grep -q \"git_identity_hook.sh\" \"$BASHRC\" 2>/dev/null; then\n    echo \"⚠️  Hook 已启用，无需重复激活\"\n    echo \"\"\n    exit 0\nfi\n\n# 直接调用激活脚本\necho \"🔧 重新激活 Git 身份自动配置...\"\necho \"\"\n\nbash \"$(dirname \"${BASH_SOURCE[0]}\")/activate_git_identity_hook.sh\n\necho \"\"\necho \"=======================================================================\" echo \"   ✅ 恢复完成！\" echo \"=======================================================================\" echo \"\" echo \"📋 验证方式：\" echo \"\" echo \"  1. 重新加载 shell 配置：\" echo \"     source ~/.bashrc  (或 ~/.zshrc)\" echo \"\" echo \"  2. 进入项目目录测试：\" echo \"     cd /home/mijiao/ckyf_vision\" echo \"\" echo \"  3. 查看 Git 身份：\" echo \"     git config user.name  # 应显示 robot-<机型>\" echo \"\" echo \"=======================================================================\" echo \"\"